`timescale 1ns / 1ps

// ============================================================================
// Self-Checking Phase 1 Single-Core Unified RV32IMA_Zicsr_Zifencei SoC TB
//
// Features:
//   - Loads word-per-line +HEX=<file> into unified 256 KB 128-bit backing RAM
//   - Optional commit-by-commit lockstep verification against +TRACE=<golden>
//     generated by scripts/rv32ima_asm.py (--unified --core-id <CORE_ID>)
//   - Verifies 2-wide OoO invariants via ooo_trace_mon2w (no stalls/bugs)
//   - Supports synthetic coherence snoop injection (+INJECT_SNOOP_CYC / LINE /
//     PATCH_ADDR / PATCH_VAL) to verify real end-to-end Speculative Load Replay!
// ============================================================================
module tb_single_ooo2w_p1_soc;

parameter [31:0]  CORE_ID         = 32'd0;
parameter integer MEM_LATENCY     = 4;
parameter integer ENABLE_PREFETCH = 1;

reg         clk;
reg         reset_n;
reg         ext_snoop_inv_valid;
reg  [15:0] ext_snoop_inv_line;

wire        commit0_valid, commit1_valid;
wire [31:0] commit0_seq_id, commit0_pc, commit0_instr;
wire        commit0_rd_we;
wire [4:0]  commit0_rd_addr;
wire [31:0] commit0_rd_wdata;
wire        commit0_mem_valid, commit0_mem_we;
wire [31:0] commit0_mem_addr, commit0_mem_wdata;
wire [3:0]  commit0_mem_wstrb;

wire [31:0] commit1_seq_id, commit1_pc, commit1_instr;
wire        commit1_rd_we;
wire [4:0]  commit1_rd_addr;
wire [31:0] commit1_rd_wdata;
wire        commit1_mem_valid, commit1_mem_we;
wire [31:0] commit1_mem_addr, commit1_mem_wdata;
wire [3:0]  commit1_mem_wstrb;

wire        trace_disp0_valid, trace_disp1_valid;
wire [31:0] trace_disp0_seq, trace_disp0_pc, trace_disp0_instr;
wire [31:0] trace_disp1_seq, trace_disp1_pc, trace_disp1_instr;
wire [5:0]  trace_issue_valid;
wire [191:0] trace_issue_seq;
wire [1:0]  trace_cdb_valid;
wire [63:0] trace_cdb_seq;
wire        trace_flush_valid;
wire [31:0] trace_flush_after_seq;

wire        dut_halted;
wire [31:0] dut_x14;
wire [31:0] pmu_cycles, pmu_instret;
wire [31:0] pmu_ic_hits, pmu_ic_misses, pmu_ic_pf_hits, pmu_ic_stall_cyc;
wire [31:0] pmu_dcache_hits, pmu_dcache_misses, pmu_dcache_wbs;
wire [31:0] pmu_dcache_hum, pmu_dcache_mum_cyc, pmu_mshr_coalesce;
wire [31:0] pmu_stlf_hits, pmu_br_total, pmu_br_mispred;
wire [31:0] pmu_ex_bypass_hits, pmu_ras_preds, pmu_ras_mispreds;
wire [31:0] pmu_dual_commit_cyc, pmu_replay_flushes, pmu_amo_commits, pmu_fence_commits;

wire [31:0] mon_cycles, mon_ooo_issue, mon_ooo_cdb, mon_spec_squash, mon_inv_errors;

single_ooo2w_p1_soc #(
    .CORE_ID(CORE_ID),
    .MEM_LATENCY(MEM_LATENCY),
    .ICACHE_SETS(128),
    .DCACHE_SETS(128),
    .ENABLE_PREFETCH(ENABLE_PREFETCH)
) u_dut (
    .clk(clk), .reset_n(reset_n),
    .ext_snoop_inv_valid(ext_snoop_inv_valid),
    .ext_snoop_inv_line(ext_snoop_inv_line),
    .commit0_valid(commit0_valid), .commit0_seq_id(commit0_seq_id),
    .commit0_pc(commit0_pc), .commit0_instr(commit0_instr),
    .commit0_rd_we(commit0_rd_we), .commit0_rd_addr(commit0_rd_addr), .commit0_rd_wdata(commit0_rd_wdata),
    .commit0_mem_valid(commit0_mem_valid), .commit0_mem_we(commit0_mem_we),
    .commit0_mem_addr(commit0_mem_addr), .commit0_mem_wstrb(commit0_mem_wstrb), .commit0_mem_wdata(commit0_mem_wdata),
    .commit1_valid(commit1_valid), .commit1_seq_id(commit1_seq_id),
    .commit1_pc(commit1_pc), .commit1_instr(commit1_instr),
    .commit1_rd_we(commit1_rd_we), .commit1_rd_addr(commit1_rd_addr), .commit1_rd_wdata(commit1_rd_wdata),
    .commit1_mem_valid(commit1_mem_valid), .commit1_mem_we(commit1_mem_we),
    .commit1_mem_addr(commit1_mem_addr), .commit1_mem_wstrb(commit1_mem_wstrb), .commit1_mem_wdata(commit1_mem_wdata),
    .trace_disp0_valid(trace_disp0_valid), .trace_disp0_seq(trace_disp0_seq),
    .trace_disp0_pc(trace_disp0_pc), .trace_disp0_instr(trace_disp0_instr),
    .trace_disp1_valid(trace_disp1_valid), .trace_disp1_seq(trace_disp1_seq),
    .trace_disp1_pc(trace_disp1_pc), .trace_disp1_instr(trace_disp1_instr),
    .trace_issue_valid(trace_issue_valid), .trace_issue_seq(trace_issue_seq),
    .trace_cdb_valid(trace_cdb_valid), .trace_cdb_seq(trace_cdb_seq),
    .trace_flush_valid(trace_flush_valid), .trace_flush_after_seq(trace_flush_after_seq),
    .halted(dut_halted), .x14(dut_x14),
    .pmu_cycles(pmu_cycles), .pmu_instret(pmu_instret),
    .pmu_ic_hits(pmu_ic_hits), .pmu_ic_misses(pmu_ic_misses),
    .pmu_ic_pf_hits(pmu_ic_pf_hits), .pmu_ic_stall_cyc(pmu_ic_stall_cyc),
    .pmu_dcache_hits(pmu_dcache_hits), .pmu_dcache_misses(pmu_dcache_misses),
    .pmu_dcache_wbs(pmu_dcache_wbs), .pmu_dcache_hum(pmu_dcache_hum),
    .pmu_dcache_mum_cyc(pmu_dcache_mum_cyc), .pmu_mshr_coalesce(pmu_mshr_coalesce),
    .pmu_stlf_hits(pmu_stlf_hits), .pmu_br_total(pmu_br_total), .pmu_br_mispred(pmu_br_mispred),
    .pmu_ex_bypass_hits(pmu_ex_bypass_hits), .pmu_ras_preds(pmu_ras_preds), .pmu_ras_mispreds(pmu_ras_mispreds),
    .pmu_dual_commit_cyc(pmu_dual_commit_cyc), .pmu_replay_flushes(pmu_replay_flushes),
    .pmu_amo_commits(pmu_amo_commits), .pmu_fence_commits(pmu_fence_commits)
);

ooo_trace_mon2w #(
    .MAX_SEQ(16384),
    .NUM_ISSUE_PORT(6),
    .NUM_CDB_PORT(2),
    .WATCHDOG_CYC(1024)
) u_mon (
    .clk(clk), .reset_n(reset_n), .active(!dut_halted),
    .disp0_valid(trace_disp0_valid), .disp0_seq_id(trace_disp0_seq),
    .disp0_pc(trace_disp0_pc), .disp0_instr(trace_disp0_instr),
    .disp1_valid(trace_disp1_valid), .disp1_seq_id(trace_disp1_seq),
    .disp1_pc(trace_disp1_pc), .disp1_instr(trace_disp1_instr),
    .issue_valid(trace_issue_valid), .issue_seq_id(trace_issue_seq),
    .cdb_valid(trace_cdb_valid), .cdb_seq_id(trace_cdb_seq),
    .commit0_valid(commit0_valid), .commit0_seq_id(commit0_seq_id),
    .commit1_valid(commit1_valid), .commit1_seq_id(commit1_seq_id),
    .flush_valid(trace_flush_valid), .flush_after_seq_id(trace_flush_after_seq),
    .cycle_count(mon_cycles), .ooo_issue_pairs(mon_ooo_issue),
    .ooo_cdb_pairs(mon_ooo_cdb), .spec_squashed_issued(mon_spec_squash),
    .inv_errors(mon_inv_errors)
);

initial clk = 1'b0;
always #5 clk = ~clk;

// Word-per-line loader buffer -> packed into 128-bit unified DRAM lines
reg [31:0] hex_words [0:16383];

// Optional Golden RVFI Trace File Reader
integer trace_fd;
reg     has_trace;
integer commit_idx;
integer cmp_errors;
integer max_cycles;
reg     expect_x14_en;
reg [31:0] expect_x14;
integer req_replay_min;

// Synthetic snoop-replay injection parameters
reg     inject_snoop_en;
integer inject_snoop_cyc;
reg [15:0] inject_snoop_line;
reg [19:0] inject_patch_addr;
reg [31:0] inject_patch_val;
integer sim_cyc;

reg [8*256-1:0] hex_file;
reg [8*256-1:0] trace_file;

task check_commit_lane(
    input integer lane,
    input [31:0]  c_pc,
    input [31:0]  c_instr,
    input         c_rd_we,
    input [4:0]   c_rd_addr,
    input [31:0]  c_rd_wdata,
    input         c_mem_valid,
    input         c_mem_we,
    input [31:0]  c_mem_addr,
    input [3:0]   c_mem_wstrb,
    input [31:0]  c_mem_wdata
);
    integer rc;
    integer g_step, g_rd_we, g_rd_addr, g_mv, g_mw, g_hlt;
    reg [31:0] g_pc, g_instr, g_rd_wdata, g_maddr, g_mwdata;
    reg [3:0]  g_mwstrb;
    begin
        if (has_trace) begin
            rc = $fscanf(trace_fd, "%d %h %h %d %d %h %d %d %h %h %h %d\n",
                         g_step, g_pc, g_instr, g_rd_we, g_rd_addr, g_rd_wdata,
                         g_mv, g_mw, g_maddr, g_mwstrb, g_mwdata, g_hlt);
            if (rc != 12) begin
                $display("FAIL [p1_soc]: Golden trace EOF early at commit %0d (lane%0d pc=0x%08x)",
                         commit_idx, lane, c_pc);
                cmp_errors = cmp_errors + 1;
            end else begin
                if (c_pc !== g_pc || c_instr !== g_instr) begin
                    $display("FAIL [p1_soc]: commit %0d lane%0d PC/INSTR exp=(0x%08x,0x%08x) got=(0x%08x,0x%08x)",
                             commit_idx, lane, g_pc, g_instr, c_pc, c_instr);
                    cmp_errors = cmp_errors + 1;
                end
                if (c_rd_we !== g_rd_we[0] ||
                    (g_rd_we[0] && (c_rd_addr !== g_rd_addr[4:0] || c_rd_wdata !== g_rd_wdata))) begin
                    $display("FAIL [p1_soc]: commit %0d lane%0d RD pc=0x%08x exp=(we=%0d r%0d=0x%08x) got=(we=%0d r%0d=0x%08x)",
                             commit_idx, lane, g_pc, g_rd_we, g_rd_addr, g_rd_wdata, c_rd_we, c_rd_addr, c_rd_wdata);
                    cmp_errors = cmp_errors + 1;
                end
                if (c_mem_valid !== g_mv[0] ||
                    (g_mv[0] && (c_mem_we !== g_mw[0] || c_mem_addr !== g_maddr)) ||
                    (g_mv[0] && g_mw[0] && (c_mem_wstrb !== g_mwstrb || c_mem_wdata !== g_mwdata))) begin
                    $display("FAIL [p1_soc]: commit %0d lane%0d MEM pc=0x%08x exp=(v=%0d w=%0d a=0x%08x s=%0x d=0x%08x) got=(v=%0d w=%0d a=0x%08x s=%0x d=0x%08x)",
                             commit_idx, lane, g_pc, g_mv, g_mw, g_maddr, g_mwstrb, g_mwdata,
                             c_mem_valid, c_mem_we, c_mem_addr, c_mem_wstrb, c_mem_wdata);
                    cmp_errors = cmp_errors + 1;
                end
            end
        end
        commit_idx = commit_idx + 1;
    end
endtask

/* verilator lint_off BLKSEQ */
/* verilator lint_off SYNCASYNCNET */
always @(posedge clk) begin
    if (reset_n && !dut_halted) begin
        if (commit0_valid) begin
            check_commit_lane(0, commit0_pc, commit0_instr, commit0_rd_we, commit0_rd_addr, commit0_rd_wdata,
                              commit0_mem_valid, commit0_mem_we, commit0_mem_addr, commit0_mem_wstrb, commit0_mem_wdata);
        end
        if (commit1_valid) begin
            check_commit_lane(1, commit1_pc, commit1_instr, commit1_rd_we, commit1_rd_addr, commit1_rd_wdata,
                              commit1_mem_valid, commit1_mem_we, commit1_mem_addr, commit1_mem_wstrb, commit1_mem_wdata);
        end
    end
end
/* verilator lint_on SYNCASYNCNET */
/* verilator lint_on BLKSEQ */

integer wi, li;
reg [15:0] p_laddr;
reg [6:0]  p_set;
reg [8:0]  p_tag;
reg [1:0]  p_woff;

initial begin
    reset_n             = 1'b0;
    ext_snoop_inv_valid = 1'b0;
    ext_snoop_inv_line  = 16'd0;
    commit_idx          = 0;
    cmp_errors          = 0;
    has_trace           = 1'b0;
    max_cycles          = 50000;
    expect_x14_en       = 1'b0;
    expect_x14          = 32'd0;
    req_replay_min      = 0;
    inject_snoop_en     = 1'b0;
    inject_snoop_cyc    = 0;
    inject_snoop_line   = 16'd0;
    inject_patch_addr   = 20'd0;
    inject_patch_val    = 32'd0;

    for (wi = 0; wi < 16384; wi = wi + 1)
        hex_words[wi] = 32'd0;

    if (!$value$plusargs("HEX=%s", hex_file)) begin
        $display("FAIL [tb_single_ooo2w_p1_soc]: Missing +HEX=<file>");
        $fatal(1);
    end
    $readmemh(hex_file, hex_words);

    // Pack 32-bit words into unified 128-bit DRAM lines
    for (li = 0; li < 4096; li = li + 1) begin
        u_dut.u_mem.mem[li] = {hex_words[li*4+3], hex_words[li*4+2], hex_words[li*4+1], hex_words[li*4+0]};
    end

    if ($value$plusargs("TRACE=%s", trace_file)) begin
        trace_fd = $fopen(trace_file, "r");
        if (trace_fd == 0) begin
            $display("FAIL [tb_single_ooo2w_p1_soc]: Cannot open trace %0s", trace_file);
            $fatal(1);
        end
        has_trace = 1'b1;
    end
    if ($value$plusargs("MAX_CYCLES=%d", max_cycles)) begin end
    if ($value$plusargs("EXPECT_X14=%h", expect_x14)) expect_x14_en = 1'b1;
    if ($value$plusargs("REQ_REPLAY_MIN=%d", req_replay_min)) begin end
    if ($value$plusargs("INJECT_SNOOP_CYC=%d", inject_snoop_cyc)) inject_snoop_en = 1'b1;
    if ($value$plusargs("INJECT_PATCH_ADDR=%h", inject_patch_addr)) begin end
    if ($value$plusargs("INJECT_PATCH_VAL=%h", inject_patch_val)) begin end

    repeat (2) @(posedge clk);
    @(negedge clk);
    reset_n = 1'b1;

    sim_cyc = 0;
    while (!dut_halted && sim_cyc < max_cycles) begin
        @(negedge clk);
        ext_snoop_inv_valid = 1'b0;
        if (inject_snoop_en && (sim_cyc == inject_snoop_cyc)) begin
            // Simulate peer core writing inject_patch_val to inject_patch_addr & sending snoop-inv!
            p_laddr = inject_patch_addr[19:4];
            p_set   = inject_patch_addr[10:4];
            p_tag   = inject_patch_addr[19:11];
            p_woff  = inject_patch_addr[3:2];
            case (p_woff)
                2'd0: u_dut.u_mem.mem[p_laddr[13:0]][31:0]   = inject_patch_val;
                2'd1: u_dut.u_mem.mem[p_laddr[13:0]][63:32]  = inject_patch_val;
                2'd2: u_dut.u_mem.mem[p_laddr[13:0]][95:64]  = inject_patch_val;
                2'd3: u_dut.u_mem.mem[p_laddr[13:0]][127:96] = inject_patch_val;
            endcase
            // Invalidate matching line in L1D just like a real MOESI GetM snoop!
            if (u_dut.u_dcache.way0_valid[p_set] && u_dut.u_dcache.way0_tag[p_set] == p_tag)
                u_dut.u_dcache.way0_valid[p_set] = 1'b0;
            if (u_dut.u_dcache.way1_valid[p_set] && u_dut.u_dcache.way1_tag[p_set] == p_tag)
                u_dut.u_dcache.way1_valid[p_set] = 1'b0;
            ext_snoop_inv_valid = 1'b1;
            ext_snoop_inv_line  = p_laddr;
        end
        @(posedge clk);
        sim_cyc = sim_cyc + 1;
        if (cmp_errors > 10) begin
            $display("FAIL [tb_single_ooo2w_p1_soc]: Aborting after >10 RVFI mismatches");
            $fatal(1);
        end
    end

    if (has_trace) $fclose(trace_fd);

    if (!dut_halted) begin
        $display("FAIL [tb_single_ooo2w_p1_soc]: Timeout after %0d cycles (commits=%0d)", max_cycles, commit_idx);
        $fatal(1);
    end
    if (cmp_errors != 0 || mon_inv_errors != 0) begin
        $display("FAIL [tb_single_ooo2w_p1_soc]: cmp_errors=%0d mon_inv_errors=%0d", cmp_errors, mon_inv_errors);
        $fatal(1);
    end
    if (expect_x14_en && (dut_x14 !== expect_x14)) begin
        $display("FAIL [tb_single_ooo2w_p1_soc]: x14 exp=0x%08x got=0x%08x", expect_x14, dut_x14);
        $fatal(1);
    end
    if (pmu_replay_flushes < req_replay_min) begin
        $display("FAIL [tb_single_ooo2w_p1_soc]: replay_flushes=%0d < required %0d", pmu_replay_flushes, req_replay_min);
        $fatal(1);
    end

    $display("PASS [single_ooo2w_p1]: file=%0s commits=%0d cycles=%0d IPC=%0.3f ic_h=%0d ic_m=%0d ic_pf=%0d ic_st=%0d dc_h=%0d dc_m=%0d dc_wb=%0d hum=%0d mum=%0d amo=%0d fence=%0d replay=%0d dual_c=%0d ex_byp=%0d ras=%0d/%0d x14=0x%08x",
             hex_file, commit_idx, pmu_cycles,
             (pmu_cycles > 0) ? (1.0 * pmu_instret / pmu_cycles) : 0.0,
             pmu_ic_hits, pmu_ic_misses, pmu_ic_pf_hits, pmu_ic_stall_cyc,
             pmu_dcache_hits, pmu_dcache_misses, pmu_dcache_wbs,
             pmu_dcache_hum, pmu_dcache_mum_cyc,
             pmu_amo_commits, pmu_fence_commits, pmu_replay_flushes,
             pmu_dual_commit_cyc, pmu_ex_bypass_hits,
             pmu_ras_mispreds, pmu_ras_preds, dut_x14);
    $finish;
end

endmodule
